import{_ as a,o as r,c as i,a8 as s}from"./chunks/framework.BppdKxCY.js";const p=JSON.parse('{"title":"EP.18 Worker 家族与跨 Tab","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.18-worker-family.md","filePath":"comics/EP.18-worker-family.md","lastUpdated":1793421673000}'),o={name:"comics/EP.18-worker-family.md"};function t(l,e,n,h,k,d){return r(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="ep-18-worker-家族与跨-tab" tabindex="-1">EP.18 Worker 家族与跨 Tab <a class="header-anchor" href="#ep-18-worker-家族与跨-tab" aria-label="Permalink to &quot;EP.18 Worker 家族与跨 Tab&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../18-worker-messaging">18-worker-messaging.md</a>（Worker 家族 / Service Worker 缓存与更新 / 跨 Tab 通信选型）· 示例：<code>examples/18-01-cross-tab/</code>、<code>examples/18-04-service-worker/</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君在主线程算十万行数据，三秒长任务冻结了所有点击与动画。</li><li><strong>第 2 格</strong>：码叔揭秘 Dedicated Worker：独立线程计算，postMessage 回传，UI 全程不卡。</li><li><strong>第 3 格</strong>：像素酱实证四兄弟分工，以及跨 Tab 通信的两条路（BroadcastChannel / SharedWorker）。</li><li><strong>第 4 格</strong>：码叔结案——Service Worker 新版本要 skipWaiting + 通知 reload 才会生效。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-主线程为什么不能算重活" tabindex="-1">第 1 格 · 主线程为什么不能算重活 <a class="header-anchor" href="#第-1-格-·-主线程为什么不能算重活" aria-label="Permalink to &quot;第 1 格 · 主线程为什么不能算重活&quot;">​</a></h3><ul><li>浏览器主线程同时负责 JS 执行、样式布局、绘制合成、事件响应；</li><li>一个超过 50ms 的任务就会让交互出现可感知延迟，三秒即&quot;页面已无响应&quot;；</li><li>原则：<strong>主线程只做与 UI 直接相关的事，计算卸载到 Worker</strong>。</li></ul><h3 id="第-2-格-·-dedicated-worker" tabindex="-1">第 2 格 · Dedicated Worker <a class="header-anchor" href="#第-2-格-·-dedicated-worker" aria-label="Permalink to &quot;第 2 格 · Dedicated Worker&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> w</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Worker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;calc.worker.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">postMessage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rows);                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 结构化克隆：拷贝一份传过去</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onmessage</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">e</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(e.data);</span></span></code></pre></div><ul><li>Worker 运行在独立线程，有独立事件循环；</li><li><strong>没有 <code>window</code>/<code>document</code>/DOM</strong>，能做计算、fetch、IndexedDB、定时器；</li><li>postMessage 默认<strong>结构化克隆</strong>（深拷贝，有开销）；大块二进制用 Transferable（转移所有权，零拷贝）或 SharedArrayBuffer。</li></ul><h3 id="第-3-格-·-worker-四兄弟与跨-tab" tabindex="-1">第 3 格 · Worker 四兄弟与跨 Tab <a class="header-anchor" href="#第-3-格-·-worker-四兄弟与跨-tab" aria-label="Permalink to &quot;第 3 格 · Worker 四兄弟与跨 Tab&quot;">​</a></h3><ul><li><strong>Dedicated Worker</strong>：一个页面专属，卸载计算（排序、解析、编解码）；</li><li><strong>SharedWorker</strong>：同源多个页面共享同一个工人，可作为跨 Tab 的状态中枢（端口连接，首个连接负责&quot;选主&quot;）；</li><li><strong>Service Worker</strong>：页面外的网络代理，拦截 fetch 做离线缓存、后台同步、推送；</li><li><strong>Worklet</strong>：渲染管线/音频的底层钩子（PaintWorklet、AudioWorklet）；</li><li>跨 Tab 只广播事件 → <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/BroadcastChannel" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>BroadcastChannel</code></a> 最轻；要共享一份状态/长连接 → SharedWorker。</li></ul><h3 id="第-4-格-·-service-worker-更新机制" tabindex="-1">第 4 格 · Service Worker 更新机制 <a class="header-anchor" href="#第-4-格-·-service-worker-更新机制" aria-label="Permalink to &quot;第 4 格 · Service Worker 更新机制&quot;">​</a></h3><ul><li>浏览器检测到 sw.js 字节变化 → 安装新 Worker，但<strong>旧 Worker 仍控制着所有页面</strong>，新的进入 waiting；</li><li><code>self.skipWaiting()</code> 让新 SW 安装后立即激活，配合 <code>clients.claim()</code> 接管；</li><li>前端监听 <code>controllerchange</code> 提示用户刷新（或自动 reload），否则用户仍跑旧缓存；</li><li>缓存策略要带版本号（如 <code>cache-v3</code>），activate 阶段清理旧缓存。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../18-worker-messaging#模块十-坑点速查、调试与自测">《模块十：坑点速查、调试与自测》</a></p></blockquote><ol><li>在 Worker 里写 DOM 操作报 ReferenceError：Worker 无 DOM，只能算完把结果 postMessage 回去；</li><li>频繁 postMessage 巨大对象：结构化克隆成本高，用 Transferable 转移或切片增量发送；</li><li>发布新 SW 后用户死活不更新：waiting 状态没处理——skipWaiting + controllerchange 提示 reload。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>为什么 Worker 里不能操作 DOM？——<strong>Worker 是无 DOM 的独立线程环境，只有计算/fetch/IndexedDB 等能力，UI 变更必须回传主线程执行</strong>。</li><li>BroadcastChannel 和 SharedWorker 怎么选？——<strong>只需跨 Tab 广播事件选 BroadcastChannel（轻量）；需要共享状态或共享一条长连接选 SharedWorker</strong>。</li><li>新 Service Worker 为什么不立刻生效？怎么处理？——<strong>旧 SW 仍控制页面，新的在 waiting；调用 skipWaiting + clients.claim，并监听 controllerchange 提示刷新</strong>。</li></ol>`,19)])])}const g=a(o,[["render",t]]);export{p as __pageData,g as default};
